function demoMain(idx,label){
  var baselines=[{"v1.0":12,"v1.1":12,"v1.2":15},{"v2.0":40,"v2.1":40,"v2.2":40},{"v3.0":7,"v3.1":9,"v3.2":9}];
  var b=baselines[idx%baselines.length];var vers=Object.keys(b);var regs=[];
  for(var i=1;i<vers.length;i++){if(b[vers[i]]>b[vers[i-1]])regs.push(vers[i]+" (+"+(b[vers[i]]-b[vers[i-1]])+" failures)");}
  return "["+label+"] baseline "+JSON.stringify(b)+" => "+(regs.length?"REGRESSIONS: "+regs.join(", "):"no regressions");
}

